contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint minDelay) public payable {
        require(true);

        require(address(this).balance >= amount);
        uint beforeBal = address(c).balance;
        uint beforeTime = c.pastBlockTime();

        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = address(c).balance;
        uint afterTime = c.pastBlockTime();

