contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint wait, bool advance) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        uint t0 = c.pastBlockTime();

        if (advance) {
            uint target = t0 + 1 + (wait % 1000);
            if (target <= block.timestamp) {
                target = block.timestamp + 1;
            }
            uint delta = target - block.timestamp;
            require(delta <= 10000);
            while (block.timestamp < target) {}
        }

        uint beforeTs = block.timestamp;
        bool reverted;
        try c.fallback() { value: amount }() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(c.pastBlockTime() == t0);
        } else {
            assert(c.pastBlockTime() == beforeTs);
        }
    }

    receive() external payable {}
}

