contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 pastTimeSetup) public payable {
        require(amount >= 0 && amount <= 100 ether);
        require(address(this).balance >= amount);

        // timestamp must be strictly increasing to make the setup call matter
        if (pastTimeSetup > 0) {
            require(pastTimeSetup <= block.timestamp);
            // setup call may be skipped if we only test the happy path
            try c.fallback{value: 10 ether}() {
                // if it succeeds, c.pastBlockTime() is block.timestamp now
            } catch {
                // setup call may revert; that's fine for the property
            }
        }

        bool reverted;
        uint256 beforePast = c.pastBlockTime();

        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterPast = c.pastBlockTime();

        if (amount < 10 ether) {
            assert(reverted && afterPast == beforePast);
        } else {
            // With enough value, the call either succeeds or reverts only
            // because block.timestamp <= pastBlockTime. Since we cannot
            // control block.timestamp here, we only assert the necessary
            // changed-state property on success and the unchanged-state
            // property on revert.
            if (!reverted) {
                assert(afterPast == block.timestamp);
            } else {
                assert(afterPast == beforePast);
            }
        }
    }

    receive() external payable {}
}

