        c = _c;
    }

    function run(uint amount, uint64 newTime) public payable {
        require(address(this).balance >= amount);
        require(newTime > block.timestamp);

        // First set pastBlockTime to newTime. The only way to increase it is to send
        // exactly 10 ether; we require enough balance so this setup call can succeed.
        require(address(this).balance >= 10 ether);
        bool setupReverted;
        try c.fallback{value: 10 ether}() {
            setupReverted = false;
        } catch {
            setupReverted = true;
        }
        bool afterSetupTimeIsNewTime = (c.pastBlockTime() == newTime);

        uint beforePastBlockTime = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPastBlockTime = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        // The fallback succeeds iff the sent amount is exactly 10 ether and the
        // current block.timestamp is strictly greater than the previously stored
        // pastBlockTime. On success it updates pastBlockTime to the current block;
        // on failure neither the recorded time nor c's balance changes.
        assert(
            !afterSetupTimeIsNewTime ||
            (
                (!reverted && amount == 10 ether && block.timestamp > beforePastBlockTime && afterPastBlockTime == block.timestamp && afterBalance == beforeBalance + amount) ||
                (reverted && (amount != 10 ether || block.timestamp <= beforePastBlockTime) && afterPastBlockTime == beforePastBlockTime && afterBalance == beforeBalance)
            )
        );
    }

    receive() external payable {}
}

