    function run(uint256 amount, bool useExactAmount, uint256 targetTime) public payable {
        // Read c's public state through the auto-generated getter.
        uint256 pastTimeBefore = c.pastBlockTime();
        uint256 cBalanceBefore = address(c).balance;

        // Determine the value to send. Either use exactly 10 ether, or some amount >= 10 ether.
        uint256 valueToSend;
        if (useExactAmount) {
            valueToSend = 10 ether;
        } else {
            require(amount >= 10 ether, "amount must be at least 10 ether");
            valueToSend = amount;
        }
        require(address(this).balance >= valueToSend, "insufficient balance");

        // Set up the time condition. We cannot manipulate block.timestamp directly,
        // but the test harness likely controls the timestamp at transaction execution.
        // The precondition `targetTime` is unused for direct manipulation; instead,
        // we make the test robust by relying only on observable behavior.
        // Drop unused param to avoid warnings (no-op):
        targetTime;

        // Record timestamp and block number at the time of the call.
        uint256 callBlockNumber = block.number;
        uint256 callTimestamp = block.timestamp;
        uint256 cBalanceBeforeCall = address(c).balance;
        uint256 thisBalanceBeforeCall = address(this).balance;

        // Make the call to c's fallback.
        (bool success, ) = address(c).call{value: valueToSend}("");

        // Read state after the call.
        uint256 pastTimeAfter = c.pastBlockTime();
        uint256 cBalanceAfter = address(c).balance;
        uint256 thisBalanceAfter = address(this).balance;

        // Rule:
        // 1. If valueToSend < 10 ether (impossible by precondition) call must revert.
        // 2. If callTimestamp <= pastTimeBefore, call must revert.
        // 3. If call touches c, pastBlockTime must be updated to callTimestamp only on success; on revert it must remain pastTimeBefore.
        // 4. If block.number % 15 == 0, on success the entire c balance is transferred to msg.sender (this test contract); otherwise c balance increases by valueToSend.
        bool timeCondition = callTimestamp > pastTimeBefore;
        bool numberCondition = callBlockNumber % 15 == 0;

        if (valueToSend < 10 ether || !timeCondition) {
            assert(!success);
        } else {
            assert(success);
            assert(pastTimeAfter == callTimestamp);
            if (numberCondition) {
                assert(cBalanceAfter == 0);
                assert(thisBalanceAfter == thisBalanceBeforeCall + valueToSend + cBalanceBeforeCall);
            } else {
                assert(cBalanceAfter == cBalanceBeforeCall + valueToSend);
                assert(thisBalanceAfter == thisBalanceBeforeCall - valueToSend);
            }
        }
    }

    receive() external payable {}
}

