        bool reverted;
        if (amount == 10 ether && block.timestamp > recordedBefore) {
            (bool ok,) = address(c).call{value: amount}("");
            reverted = !ok;
        } else {
            (bool ok,) = address(c).call{value: amount}("");
            reverted = !ok;
        }

        if (amount == 10 ether && block.timestamp <= recordedBefore) {
            assert(reverted == true);
        } else if (amount != 10 ether) {
            assert(reverted == true);
        } else {
            assert(reverted == false);
            assert(c.pastBlockTime() == block.timestamp);
        }
