        // (Deployment time is effectively zero on most test harnesses.)
        uint256 firstDelta;
        unchecked {
            firstDelta = timeDelta % 1000000;
        }
        if (firstDelta == 0) {
            return;
        }

        uint256 beforePast = c.pastBlockTime();

        uint256 expectedFirstRevert;
        if (amount == 10 ether && block.timestamp > beforePast) {
            expectedFirstRevert = 0;
        } else {
            expectedFirstRevert = 1;
        }

        uint256 afterFirst;
        if (expectedFirstRevert == 1) {
            afterFirst = beforePast;
        } else {
            afterFirst = block.timestamp;
        }

        uint256 secondDelta;
        unchecked {
            secondDelta = firstDelta + 1;
        }

        uint256 expectedSecondRevert;
        if (amount == 10 ether && block.timestamp + secondDelta > afterFirst) {
            expectedSecondRevert = 0;
        } else {
            expectedSecondRevert = 1;
        }

        // First call: amount is taken as a parameter; never read msg.value.
        // By construction, amount == 10 ether implies address(this).balance >= 10 ether
        // because the test function is payable and the caller funds it.
        bool firstReverted;
        try c.call{value: amount}("") {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint256 afterFirstActual = c.pastBlockTime();

        // Second call: same amount, after a strictly positive timeDelta.
        bool secondReverted;
        try c.call{value: amount}("") {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint256 afterSecondActual = c.pastBlockTime();

        // General exhaustively branchable rule.
        assert(
            (firstReverted ? 1 : 0) == expectedFirstRevert &&
            afterFirstActual == afterFirst &&
            (secondReverted ? 1 : 0) == expectedSecondRevert &&
            (secondReverted ? afterSecondActual == afterFirst : true)
        );
    }

