        balanceBefore2 = address(this).balance;

        // Second call: the timestamp is strictly greater than t1, so it should succeed only if amount == 10 ether.
        bool reverted2;
        uint blockNumber = block.number;

        try c.call{value: amount}("") {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        uint past = c.pastBlockTime();
        uint cBalance = address(c).balance;

        // General rule: fallback reverts iff the sent value is not exactly 10 ether or the timestamp condition fails.
        // On success, pastBlockTime matches the timestamp of the successful call.
        assert(
            reverted2 == (amount != 10 ether || t2 <= observedTs) &&
            (reverted2 || past == t2) &&
            (reverted2 || cBalance == 10 ether || (blockNumber % 15 == 0 && cBalance == 0))
        );
    }
}

