contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint amount, uint64 targetTime) public payable {
        require(amount >= 10 ether, "need to cover value");
        require(address(this).balance >= amount, "balance too low");

        // Fresh c has pastBlockTime = 0, so any targetTime is
        // <= pastBlockTime only when targetTime == 0 (or 0 value).
        // We compare against the observed before-value rather than
        // relying on that.
        uint before = c.pastBlockTime();

        // Drive the state so the deciding call's precondition is
        // determined by targetTime relative to the observed before.
        uint64 nowTs = uint64(block.timestamp);
        bool canSucceed = (targetTime > before);

        bool reverted;
        uint balBefore = address(c).balance;

        if (canSucceed) {
            // targetTime may be in the future; but requires isn't testable.
            // Only make the deciding call when we know it can succeed per policy:
            // caller must supply exactly pastBlockTime+something? We use block.timestamp.
            // Instead, only call when targetTime == block.timestamp means success.
            // So restrict to targetTime == nowTs.
            require(targetTime == nowTs, "future target unsupported");
            require(nowTs > before, "timestamp must advance");
            c.fallback{value: amount}();
            reverted = false;
        } else {
            // targetTime <= before: any call must revert (must exceed pastBlockTime).
            try c.fallback{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (!reverted && canSucceed) {
            // success path: pastBlockTime advanced to nowTs
            assert(c.pastBlockTime() == nowTs);
        } else {
            // revert path: state unchanged
            assert(c.pastBlockTime() == before);
        }
    }

    receive() external payable {}
}

