contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint waitTime) public payable {
        // amount must be exactly 10 ether to satisfy the value requirement
        require(amount == 10 ether, "amount must be 10 ether");
        require(address(this).balance >= amount, "insufficient balance");

        // First call sets pastBlockTime to the current block timestamp (if it succeeds).
        // We make a valid call first so that timestamps can be compared reproducibly.
        bool firstReverted;
        try c.call{value: amount}() { firstReverted = false; } catch { firstReverted = true; }

        // Only proceed if the first call succeeded, so the rule's precondition is stable.
        require(!firstReverted, "initial call must succeed");

        // Record the state after the first call.
        uint beforeTime = c.pastBlockTime();

        // Make a second fallback call with a timestamp that is strictly greater by waitTime.
        // We cannot control block.timestamp in a real EVM, so we instead construct an
        // input condition that requires the current timestamp to be strictly greater than
        // the previous one. The checker will run this in a fresh block, where the timestamp
        // is the same as the first call's timestamp. Thus the second call must revert if
        // the timestamp is not strictly greater than pastBlockTime.
        bool secondReverted;
        try c.call{value: amount}() { secondReverted = false; } catch { secondReverted = true; }

        // General rule: a call with no value or wrong value must revert, but here we
        // specifically assert the relationship between the two calls in the same block.
        // Because both calls happen in the same transaction and hence the same block,
        // block.timestamp is identical. The second call must revert because the required
        // block.timestamp > pastBlockTime is violated (equal, not greater).
        // If the second call does not revert, the contract would have allowed a call with
        // a timestamp that is not strictly greater, violating the expected rule.
        assert(secondReverted || block.timestamp > beforeTime);
    }

    receive() external payable {}
}

